using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.DependencyInjection; using MyFundex.BuildingBlocks.Abstractions; using MyFundex.BuildingBlocks.Domain; using MyFundex.BuildingBlocks.Persistence;
namespace MyFundex.MasterData;
public sealed class Country:EntityBase{public Guid CountryId{get;set;} public string Code{get;set;}=""; public string Name{get;set;}="";}
public sealed class Currency:EntityBase{public Guid CurrencyId{get;set;} public string Code{get;set;}="INR"; public string Name{get;set;}="Indian Rupee"; public int DecimalPlaces{get;set;}=2;}
public sealed class Exchange:EntityBase{public Guid ExchangeId{get;set;} public string Code{get;set;}="NSE"; public string Name{get;set;}="National Stock Exchange";}
public sealed class SecurityType:EntityBase{public Guid SecurityTypeId{get;set;} public string Code{get;set;}="EQUITY"; public string Name{get;set;}="Equity";}
public sealed class MasterDataDbContext(DbContextOptions<MasterDataDbContext> o, ICurrentActor a):AuditableDbContext(o,a){public DbSet<Country> Countries=>Set<Country>(); public DbSet<Currency>Currencies=>Set<Currency>(); public DbSet<Exchange>Exchanges=>Set<Exchange>(); public DbSet<SecurityType>SecurityTypes=>Set<SecurityType>(); protected override void OnModelCreating(ModelBuilder m) => ConfigureModel(m); public static void ConfigureModel(ModelBuilder m) {m.HasDefaultSchema("master"); ConfigureEntity(m.Entity<Country>());ConfigureEntity(m.Entity<Currency>());ConfigureEntity(m.Entity<Exchange>());ConfigureEntity(m.Entity<SecurityType>());m.Entity<Country>().HasIndex(x=>x.Code).IsUnique().HasFilter("\"IsDeleted\" = false");m.Entity<Currency>().HasIndex(x=>x.Code).IsUnique().HasFilter("\"IsDeleted\" = false");m.Entity<Exchange>().HasIndex(x=>x.Code).IsUnique().HasFilter("\"IsDeleted\" = false");m.Entity<SecurityType>().HasIndex(x=>x.Code).IsUnique().HasFilter("\"IsDeleted\" = false");}}
public static class MasterDataModule{public static IServiceCollection AddMasterDataModule(this IServiceCollection s,string cs){s.AddDbContext<MasterDataDbContext>(o=>o.UseNpgsql(cs));return s;}}
